// Cloudflare Workers run IN the network, at the edge
// ~0ms cold start, runs in every Cloudflare datacenter simultaneously
// Powered by V8 isolates (not Node.js)

export interface Env {
  // KV namespace binding for key-value storage
  KV: KVNamespace;
  // R2 bucket binding for object storage
  BUCKET: R2Bucket;
  // Secret environment variable
  API_KEY: string;
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    // Route: GET /api/user/:id
    if (url.pathname.startsWith('/api/user/')) {
      const userId = url.pathname.split('/').pop()!;

      // KV Store: ultra-fast global key-value
      const cached = await env.KV.get(`user:${userId}`);
      if (cached) {
        return new Response(cached, {
          headers: { 'Content-Type': 'application/json', 'X-Cache': 'HIT' },
        });
      }

      // Fetch from origin and cache
      const user = await fetch(`https://api.myapp.com/users/${userId}`);
      const data = await user.text();
      await env.KV.put(`user:${userId}`, data, { expirationTtl: 300 });  // cache 5 min
      return new Response(data, {
        headers: { 'Content-Type': 'application/json', 'X-Cache': 'MISS' },
      });
    }

    return new Response('Not found', { status: 404 });
  },
};
